// Migration 0053 — companion records: finished games of the table companions
// the server doesn't run (the Blood on the Clocktower Grimoire and the D&D DM
// screen), for the recording member's Match History.
//
// One row per game the member ran. `client_id` is generated by the client
// when the game starts, so a retried or re-sent save replaces its own row
// (`UNIQUE (user_id, client_id)`) instead of adding another. `record_json` is
// `CompanionRecordSchema` (core/protocol/http/companion-records.ts); the two
// timestamps are lifted out of it for ordering.

import type { Migration } from "./types.ts";

export const companionRecords: Migration = {
  version: 53,
  name: "companion_records",
  statements: [
    `CREATE TABLE IF NOT EXISTS companion_records (
       id INTEGER PRIMARY KEY AUTOINCREMENT,
       user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
       game_slug TEXT NOT NULL,
       client_id TEXT NOT NULL,
       record_json TEXT NOT NULL,
       started_at TEXT,
       ended_at TEXT NOT NULL,
       created_at TEXT NOT NULL DEFAULT (datetime('now')),
       updated_at TEXT NOT NULL DEFAULT (datetime('now')),
       UNIQUE (user_id, client_id)
     )`,
    "CREATE INDEX IF NOT EXISTS companion_records_user_game ON companion_records(user_id, game_slug, ended_at)",
  ],
};
